      "summary": "在今天的华为鸿蒙电脑新品技术沟通会上，华为终端 BG 平板与 PC 产品线总裁朱懂东分享了鸿蒙电脑最新取得的成绩。鸿蒙电脑外设生态日趋繁荣，目前已支持 1700+ 通用设备（键盘 / 鼠标 / 显示器 / 耳机……）、1600+ 专业设备（打印机 / 扫描仪 / 手写板 / 柜外清……）。",
